function calculate(config={},options={}){const cfg={volume:12,correctLag:true,context:true,detectorThreshold:.65,...config},key=JSON.stringify([cfg.context,cfg.detectorThreshold]);if(!cache.has(key))cache.set(key,D.training(cfg));const train=cache.get(key),settings={...cfg,...train.chosen,...config},dataset=D.generate(17,{noise:.12,...options});const results=C.infer(dataset.observations,train.model,settings);return {dataset,train,settings,results,metrics:dataset.evaluationTruth?C.evaluate(results,dataset.evaluationTruth):null};}
function realDataHTML(real){if(!real)return '';return `<details><summary>真实顶空气读数：原表 ${real.rows.length} 条</summary><p class="m2-note">${esc(real.authors)} · ${esc(real.wellId)} · ${esc(real.license)}。回收沉积物装瓶后测顶空气，保留平行样品身份。ppmv表示每百万份体积中的气体份数；下方单列原始组分记录，可对照采样方式与深度基准。</p><div id="references" class="m2-table-scroll" style="max-height:420px;overflow:auto"><table><thead><tr><th>源行 / 样品</th><th>IGSN</th><th>沉积物深度 m</th><th>CH4 ppmv</th><th>C2H6 ppmv</th></tr></thead><tbody>${real.rows.map(v=>`<tr><td>${v.sourceRow} · ${esc(v.sample)}</td><td>${esc(v.IGSN)}</td><td>${v.depth_m}</td><td>${v.CH4_ppmv}</td><td>${v.C2H6_ppmv}</td></tr>`).join('')}</tbody></table></div><p class="m2-note">数值保持原表，来源：<a href="${real.source}" target="_blank" rel="noopener">PANGAEA975497</a>。深度沿用原资料的沉积物测量基准。</p></details>`;}
