const guide=(a,b,c)=>`<div class="m2-figure-reading"><p><b>看哪里</b>${a}</p><p><b>为何这样画</b>${b}</p><p><b>能得出什么</b>${c}</p></div>`;
function neighborsTable(r,i=0){const v=r.results[i];if(!v)return '<p class="m2-empty">当前阈值下未检测到气峰。</p>';const p=v.prediction;return `<div class="m2-table-scroll"><table><caption class="m2-note">实际前三近邻 · 训练事件库 ${r.train.trainCount} 个事件</caption><thead><tr><th>顺位 / 训练井</th><th>训练事件类别</th><th>相似性距离</th><th>加权票数</th></tr></thead><tbody>${p.neighbors.slice(0,3).map((n,j)=>`<tr><td>${j+1} · ${esc(r.train.model.samples[n.index].group)}</td><td>${name(n.label)}</td><td>${fmt(n.distance,3)}</td><td>${fmt(1/Math.max(.05,n.distance),2)}</td></tr>`).join('')}</tbody></table></div><p class="m2-note">按全部 ${p.neighbors.length} 个近邻投票；距离越小权重越大，权重 = 1 / max(0.05, 距离)。支持度为获胜类别的票数占比 ${fmt(p.support*100,1)}%，表示这次近邻投票的一致程度。</p>`;}
function comparison(r,i=0){const context=r.settings.context,other=calculate({...r.settings,context:!context},r.dataset.metadata.options),a=context?other:r,b=context?r:other;return `<div class="m2-table-scroll"><table><caption class="m2-note">同一气峰、同一气测输入；两种方法各用训练井拟合对应特征</caption><thead><tr><th>输入视角</th><th>工况特征</th><th>实际相似事件</th><th>候选 / 加权票数占比</th></tr></thead><tbody>${[a,b].map((q,j)=>{const v=q.results[i];if(!v)return '';const n=v.prediction.neighbors[0];return `<tr><td>${j?'加入来源工况':'只看气峰特征'}</td><td>${j?`距接单根作业的时间间隔 ${fmt(v.features.connectionDistance_s,0)} s<br>距起下钻作业的时间间隔 ${fmt(v.features.tripDistance_s,0)} s`:'峰高、峰宽、面积、升降速率、组分变化'}</td><td>${esc(q.train.model.samples[n.index].group)}<br>距离 ${fmt(n.distance,3)}</td><td>${name(v.prediction.label)}<br>${fmt(v.prediction.support*100,1)}%</td></tr>`;}).join('')}</tbody></table></div><p class="m2-note">两行分别按6维与11维特征寻找近邻，可对照各自的训练事件与投票结果。固定规则基线给出：${name(r.results[i]?.baseline)}。</p>`;}
