  const values=valid.map(v=>v[t.key]),min=Math.min(...values),max=Math.max(...values),left=85+j*190,x=v=>left+((v-min)/(max-min||1))*130;
  plot+='<text x="'+left+'" y="17" font-size="15" fill="#343941">'+t.name+'</text><text x="'+left+'" y="34" font-size="13" fill="#62636a">'+fmt(min,1)+' → '+fmt(max,1)+'</text><path d="'+series(rows,v=>v[t.key],x,y,C.valid)+'" fill="none" stroke="'+t.color+'" stroke-width="2"/>';
  if(C.valid(selected))plot+='<circle cx="'+x(selected[t.key]).toFixed(1)+'" cy="'+y(selected.depthMD_m).toFixed(1)+'" r="4" fill="'+t.color+'" stroke="#fff" stroke-width="1"/>';
